// backend/src/lib/documents/persistGeneratedDocument.ts
//
// The generic "generated bytes → first-class documents + document_versions row"
// persistence sequence, lifted out of recordings/artifacts.ts's
// persistGeneratedArtifact so any producer (the recordings timeline PNG, the
// chat image tools, future generators) can reuse ONE copy of the insert logic
// instead of duplicating it.
//
// The `documents` schema is free-text `file_type` (schema.sql: no CHECK) and a
// nullable `pdf_storage_path` on the version, so a PNG/MP3/PDF needs NO
// type-specific fields — the same shape works for any binary. Any failure
// THROWS (callers own retry/surfacing). Attached to `projectId` when present
// (null → standalone, e.g. a main-chat generation with no matter).

import crypto from "node:crypto";
import type { createServerSupabase } from "../supabase";
import { generatedDocKey, uploadFile } from "../storage";
import {
    describeSupabaseError,
    insertDocumentVersionCompat,
} from "../documentVersions";
import {
    layoutQaVersionValues,
    verifyDerivedArtifact,
} from "../documentLayoutGate";

type Db = ReturnType<typeof createServerSupabase>;

export interface PersistGeneratedDocumentDeps {
    uploadFile: typeof uploadFile;
    verifyDerivedArtifact: typeof verifyDerivedArtifact;
}

const DEFAULT_DEPS: PersistGeneratedDocumentDeps = {
    uploadFile,
    verifyDerivedArtifact,
};

/**
 * Persist `bytes` as a first-class documents + document_versions row owned by
 * `userId`, attached to `projectId` when present, so the artifact inherits the
 * download + email-attachment rails.
 *   - filename = "<sanitized title> - <label>.<extension>" (title maps to
 *     `filename`; there is no title column). Sanitization: an ASCII hyphen
 *     separator survives the [a-zA-Z0-9 -] filter, then trim + 64-char cap,
 *     with `label` as the stem fallback for a title that sanitizes to empty.
 *   - documents.file_type = `fileType`, the object uploaded with `contentType`.
 *   - a fresh random id keys the storage object only; the documents ROW id is
 *     the DB-generated one read back.
 *   - the bytes are re-sliced to a standalone ArrayBuffer before upload (a
 *     Buffer from a converter/decoder can be a view into a pooled buffer).
 * Returns the new ids + the resolved filename.
 */
export async function persistGeneratedDocument(params: {
    db: Db;
    userId: string;
    projectId?: string | null;
    /** Human title; combined with `label` into the stored filename. */
    title: string;
    /** Filename suffix after " - " and the sanitized-empty fallback stem. */
    label: string;
    /** File extension without a dot: "pdf" | "mp3" | "png". */
    extension: string;
    /** documents.file_type (free text; e.g. "pdf" | "mp3" | "png"). */
    fileType: string;
    /** Upload content-type (e.g. "application/pdf" | "audio/mpeg" | "image/png"). */
    contentType: string;
    bytes: Buffer;
    /** Known source text that must survive PDF generation (never persisted). */
    expectedText?: string;
    /** document_versions.metadata.derivation_kind provenance tag. */
    derivationKind: string;
    /** Extra provenance merged into document_versions.metadata (e.g. recording_id). */
    extraMetadata?: Record<string, unknown>;
    deps?: Partial<PersistGeneratedDocumentDeps>;
}): Promise<{ documentId: string; versionId: string; filename: string }> {
    const deps = { ...DEFAULT_DEPS, ...params.deps };
    const { db, bytes } = params;
    const qaReport = await deps.verifyDerivedArtifact({
        bytes,
        fileType: params.fileType,
        trackedViews: false,
        expectedText: params.expectedText,
    });

    const displayTitle = `${params.title?.trim() || "Document"} - ${params.label}`;
    const safeTitle =
        displayTitle
            .replace(/[^a-zA-Z0-9 -]/g, "")
            .trim()
            .slice(0, 64) || params.label;
    const filename = `${safeTitle}.${params.extension}`;

    const keyId = crypto.randomUUID().replace(/-/g, "");
    const key = generatedDocKey(params.userId, keyId, filename);

    const arrayBuffer = bytes.buffer.slice(
        bytes.byteOffset,
        bytes.byteOffset + bytes.byteLength,
    ) as ArrayBuffer;
    await deps.uploadFile(key, arrayBuffer, params.contentType);

    const { data: docRow, error: docErr } = await db
        .from("documents")
        .insert({
            project_id: params.projectId ?? null,
            user_id: params.userId,
            filename,
            file_type: params.fileType,
            size_bytes: bytes.byteLength,
            status: "ready",
        })
        .select("id")
        .single();
    if (docErr || !docRow) {
        throw new Error(
            `Failed to record ${params.label} document: ${describeSupabaseError(docErr)}`,
        );
    }
    const documentId = docRow.id as string;

    const versionRow = await insertDocumentVersionCompat({
        db,
        fallbackSource: "generated",
        errorMessage: `Failed to record ${params.label} document version.`,
        values: {
            document_id: documentId,
            storage_path: key,
            source: "generated",
            version_number: 1,
            display_name: filename,
            created_by_user_id: params.userId,
            metadata: {
                derivation_kind: params.derivationKind,
                ...(params.extraMetadata ?? {}),
                ...(qaReport
                    ? {
                          layout_qa: {
                              status: "passed",
                              schema_version: qaReport.schema_version,
                              checked_at: qaReport.checked_at,
                          },
                      }
                    : {}),
            },
            ...(qaReport ? layoutQaVersionValues(qaReport) : {}),
        },
    });
    const versionId = versionRow.id;

    const { error: activateError } = await db
        .from("documents")
        .update({ current_version_id: versionId })
        .eq("id", documentId);
    if (activateError) {
        throw new Error(
            `Verified ${params.label} document could not be activated: ${describeSupabaseError(activateError)}`,
        );
    }

    return { documentId, versionId, filename };
}
